package endpointservice

import (
	"context"
	"crypto/sha256"
	"encoding/json"
	"errors"
	"fmt"
	"net/netip"
	"net/url"
	"strings"
	"time"
)

// NativeUIScope is generated by the authenticated Go host, never renderer input.
type NativeUIScope struct {
	ServerURL     string `json:"serverUrl"`
	UserID        string `json:"userId"`
	Epoch         string `json:"epoch"`
	Generation    uint64 `json:"generation"`
	Authenticated bool   `json:"authenticated"`
}

const nativeUIScopeTTL = 30 * time.Second

func normalizeNativeUIScope(s NativeUIScope) (NativeUIScope, error) {
	u, err := url.Parse(strings.TrimSpace(s.ServerURL))
	if err != nil || u.Host == "" || u.Hostname() == "" || u.User != nil || u.RawQuery != "" || u.Fragment != "" || (u.Scheme != "https" && u.Scheme != "http") || (u.Path != "" && u.Path != "/") {
		return s, errors.New("invalid native UI server")
	}
	s.ServerURL = strings.TrimRight(u.String(), "/")
	if !identifierPattern.MatchString(s.Epoch) || len(s.Epoch) < 16 || len(s.Epoch) > 128 || s.Generation == 0 || len(s.UserID) > 128 || strings.TrimSpace(s.UserID) != s.UserID || strings.IndexFunc(s.UserID, func(r rune) bool { return r < 32 || r == 127 }) >= 0 || s.Authenticated && s.UserID == "" {
		return s, errors.New("invalid native UI scope")
	}
	return s, nil
}
func (c Config) nativeUIBinding() (string, string, error) {
	if c.NativeUIServerURL == "" || c.NativeUIUserID == "" {
		return "", "", errors.New("native_ui_binding_required")
	}
	s, err := normalizeNativeUIScope(NativeUIScope{ServerURL: c.NativeUIServerURL, UserID: c.NativeUIUserID, Epoch: "operator-binding-v1", Generation: 1, Authenticated: true})
	if err != nil {
		return "", "", errors.New("native_ui_binding_invalid")
	}
	if !nativeUITrustedServer(s.ServerURL) {
		return "", "", errors.New("native_ui_server_untrusted")
	}
	return s.ServerURL, s.UserID, nil
}
func (n *nativeInterception) uiScopeReason(c *MihomoConfiguration) string {
	if !nativeUITrustedServer(n.uiScope.ServerURL) && n.uiScope.ServerURL != "" {
		return "native_ui_server_untrusted"
	}
	if n.uiExpectedServer == "" || n.uiExpectedUser == "" {
		return "native_ui_binding_required"
	}
	if !n.uiScope.Authenticated || n.uiPeerPID == 0 || n.uiScope.Epoch == "" {
		return "native_ui_scope_required"
	}
	if n.uiScope.ServerURL != n.uiExpectedServer || n.uiScope.UserID != n.uiExpectedUser {
		return "native_ui_scope_mismatch"
	}
	if n.uiLease.Load() <= time.Now().UnixNano() {
		return "native_ui_scope_expired"
	}
	if c != nil && c.Projection != nil && c.Projection.Credential.UserID != n.uiExpectedUser {
		return "native_ui_principal_mismatch"
	}
	return ""
}
func (e *CoordinatedExecutor) SetNativeUIScope(ctx context.Context, peer NativePeer, input NativeUIScope) (InterceptionStatus, error) {
	e.mu.Lock()
	defer e.mu.Unlock()
	n := e.native
	if n == nil {
		return InterceptionStatus{}, errors.New("native interception not configured")
	}
	if peer.session == nil || peer.pid == 0 || peer.owner != peer.session.Owner() || peer.session.Validate(ctx, false) != nil {
		if peer.session != nil {
			peer.session.Close()
		}
		return n.status, errors.New("trusted native host required")
	}
	defer peer.session.Close()
	scope, err := normalizeNativeUIScope(input)
	if err != nil {
		return n.status, err
	}
	key := peer.owner.UserID + "/" + peer.owner.SessionID + "/" + scope.Epoch
	if n.uiRetired[key] {
		return n.status, errors.New("native UI epoch retired")
	}
	sameSource := n.uiScope.Epoch == scope.Epoch && n.uiPeerPID == peer.pid && n.uiOwner == peer.owner
	if !sameSource && n.uiScope.Epoch == scope.Epoch {
		return n.status, errors.New("native UI epoch belongs to another host")
	}
	if sameSource && scope.Generation < n.uiScope.Generation {
		return n.status, errors.New("stale native UI scope")
	}
	if sameSource && scope.Generation == n.uiScope.Generation && scope != n.uiScope {
		return n.status, errors.New("native UI generation reused")
	}
	expired := n.uiLease.Load() <= time.Now().UnixNano()
	identityChanged := !sameSource || scope.ServerURL != n.uiScope.ServerURL || scope.UserID != n.uiScope.UserID
	if !sameSource && n.uiScope.Epoch != "" {
		if n.uiRetired == nil {
			n.uiRetired = map[string]bool{}
		}
		if len(n.uiRetired) >= 64 {
			return n.status, errors.New("native UI epoch limit exceeded")
		}
		n.uiRetired[n.uiOwner.UserID+"/"+n.uiOwner.SessionID+"/"+n.uiScope.Epoch] = true
	}
	hasNative := n.session != nil || n.journal.Pending || len(n.journal.Steps) > 0 || n.journal.Process != nil || n.journal.CacheFlushPending || n.journal.DNSReleasePending
	mustPause := hasNative && (identityChanged || expired || !scope.Authenticated || scope.ServerURL != n.uiExpectedServer || scope.UserID != n.uiExpectedUser || n.status.CleanupPending)
	if mustPause {
		n.guard.set(nil, true)
	}
	n.uiScope = scope
	n.uiPeerPID = peer.pid
	n.uiOwner = peer.owner
	until := time.Now().Add(nativeUIScopeTTL)
	if !scope.Authenticated || !nativeUITrustedServer(scope.ServerURL) || scope.ServerURL != n.uiExpectedServer || scope.UserID != n.uiExpectedUser {
		until = time.Now()
	}
	n.uiLease.Store(until.UnixNano())
	lease := &n.uiLease
	time.AfterFunc(time.Until(until), func() { n.guard.expireUIScope(lease) })
	if mustPause || hasNative && n.uiScopeReason(n.base) != "" {
		n.guard.set(nil, true)
		if n.journal.Request.SystemProxy || n.journal.Request.TUN {
			if n.journal.Generation == ^uint64(0) {
				return n.status, errors.New("native generation exhausted")
			}
			old := n.journal.Generation
			n.journal.Generation++
			n.journal.Request = InterceptionIntent{RequestID: randomID(), ExpectedGeneration: old}
			n.status.Generation = n.journal.Generation
		}
		if err := saveNativeJournal(n.path, n.journal); err != nil {
			n.status.State = interceptionCleanupPending
			n.status.CleanupPending = true
			return n.status, err
		}
		if err := e.restoreNativeLocked(ctx, true); err != nil {
			return n.status, err
		}
		n.status.State = interceptionSuspended
		n.status.ReasonCode = "native_ui_scope_changed"
	}
	return e.nativeStatusLocked(), nil
}
func (e *CoordinatedExecutor) nativeStatusLocked() InterceptionStatus {
	n := e.native
	view := n.status
	if view.Capabilities.SystemProxy || view.Capabilities.TUN {
		if reason := n.uiScopeReason(n.base); reason != "" {
			view.Capabilities = InterceptionCapabilities{ReasonCode: reason}
		}
	}
	return view
}

func nativeUIScopeBinding(s NativeUIScope) string {
	raw, _ := json.Marshal([]string{s.ServerURL, s.UserID, s.Epoch})
	return fmt.Sprintf("sha256:%x", sha256.Sum256(raw))
}

func nativeUITrustedServer(origin string) bool {
	u, err := url.Parse(origin)
	if err != nil {
		return false
	}
	if u.Scheme == "https" {
		return true
	}
	if u.Scheme != "http" {
		return false
	}
	ip, err := netip.ParseAddr(u.Hostname())
	return u.Hostname() == "localhost" || err == nil && ip.IsLoopback()
}
